{"record_id": "eu_german-F0002", "review_ref": "eu_german-R001", "kind": "feedback", "market": "EU", "country": "DE", "brand": "Mercedes-Benz", "model": "E-Class T-Modell", "generation": "W214", "model_year": "2024", "powertrain": "ICE", "source_type": "press_review", "source_name": "ADAC Autotest", "url": "https://assets.adac.de/image/upload/Autodatenbank/Autotest/at6421-mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic/mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic.pdf", "published": "2024-09", "feedback_type": "Likes", "theme": "ride_handling", "vfc_level2": "Handling / Riding", "comparison": null, "statement": "Reviewer states driving stability and agility surpass the already excellent predecessor; the car passes the ADAC evasion test easily and combines composure with agility like no other car in the class.", "quote": null, "language": "de", "rating": "1.8 (ADAC grade, 1=best)", "evidence_tier": "B"}
{"record_id": "eu_german-F0003", "review_ref": "eu_german-R001", "kind": "feedback", "market": "EU", "country": "DE", "brand": "Mercedes-Benz", "model": "E-Class T-Modell", "generation": "W214", "model_year": "2024", "powertrain": "ICE", "source_type": "press_review", "source_name": "ADAC Autotest", "url": "https://assets.adac.de/image/upload/Autodatenbank/Autotest/at6421-mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic/mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic.pdf", "published": "2024-09", "feedback_type": "Likes", "theme": "ride_handling", "vfc_level2": "Steering", "comparison": null, "statement": "Reviewer states the standard steering is direct (2.3 turns lock to lock), precise and gives good feedback, among the best in the class; rear-axle steering is offered for the saloon but not the estate (except E 53 AMG).", "quote": null, "language": "de", "rating": "1.8 (ADAC grade, 1=best)", "evidence_tier": "B"}
{"record_id": "eu_german-F0004", "review_ref": "eu_german-R001", "kind": "feedback", "market": "EU", "country": "DE", "brand": "Mercedes-Benz", "model": "E-Class T-Modell", "generation": "W214", "model_year": "2024", "powertrain": "ICE", "source_type": "press_review", "source_name": "ADAC Autotest", "url": "https://assets.adac.de/image/upload/Autodatenbank/Autotest/at6421-mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic/mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic.pdf", "published": "2024-09", "feedback_type": "Difficult to Use", "theme": "ride_handling", "vfc_level2": "Braking", "comparison": null, "statement": "Reviewer states the brake pedal feels doughy with an undefined pressure point, making precise, smooth stopping a real challenge (although the measured 31.0 m from 100 km/h is sports-car level).", "quote": "Zu teigig fühlt sich das Bremspedal bei Betätigung an", "language": "de", "rating": "1.8 (ADAC grade, 1=best)", "evidence_tier": "B"}
{"record_id": "eu_german-F0005", "review_ref": "eu_german-R001", "kind": "feedback", "market": "EU", "country": "DE", "brand": "Mercedes-Benz", "model": "E-Class T-Modell", "generation": "W214", "model_year": "2024", "powertrain": "ICE", "source_type": "press_review", "source_name": "ADAC Autotest", "url": "https://assets.adac.de/image/upload/Autodatenbank/Autotest/at6421-mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic/mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic.pdf", "published": "2024-09", "feedback_type": "Difficult to Use", "theme": "hmi_infotainment", "vfc_level2": "Multi-function steering wheel operation", "comparison": null, "statement": "Reviewer strongly criticises the touch surfaces on the steering wheel as impractical to frustrating; mis-operation happens daily and is hard to avoid even after long familiarisation.", "quote": "diese unpraktischen bis frustrierenden Bedienelemente", "language": "de", "rating": "1.8 (ADAC grade, 1=best)", "evidence_tier": "B"}
{"record_id": "eu_german-F0006", "review_ref": "eu_german-R001", "kind": "feedback", "market": "EU", "country": "DE", "brand": "Mercedes-Benz", "model": "E-Class T-Modell", "generation": "W214", "model_year": "2024", "powertrain": "ICE", "source_type": "press_review", "source_name": "ADAC Autotest", "url": "https://assets.adac.de/image/upload/Autodatenbank/Autotest/at6421-mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic/mercedes-benz-e-220-d-t-modell-amg-line-premium-4matic-9g-tronic.pdf", "published": "2024-09", "feedback_type": "Difficult to Use", "theme": "hmi_infotainment", "vfc_level2": "Touch screen, operation", "comparison": null, "statement": "Reviewer states the small touch slider for volume below the central screen does not allow precise adjustment and puts the small volume roller of earlier models at the top of the wish list.", "quote": "Auf der Wunschliste steht ganz oben die kleine Lautstärkenwalze", "language": "de", "rating": "1.8 (ADAC grade, 1=best)", "evidence_tier": "B"}
